    if len(result) != len(vals):
        return False

    # Check that each element at position k is the maximum of vals[0] through vals[k]
    for k in range(len(result)):
        # Compute the maximum from vals[0] to vals[k] inclusive
        max_val = vals[0]
        for i in range(1, k + 1):
            if vals[i] > max_val:
                max_val = vals[i]

        # Verify result[k] matches this maximum
        if result[k] != max_val:
